"import React, { useEffect, useState } from 'react';
import { fetchGrievances } from '../api';
import { Grievance, UserProfile } from '../types';

interface Props {
  currentUser: UserProfile;
  onBack: () => void;
}

export const DepartmentDashboard: React.FC<Props> = ({ currentUser, onBack }) => {
  const [tickets, setTickets] = useState<Grievance[]>([]);

  useEffect(() => {
    const load = async () => {
      try {
        const all = await fetchGrievances();
        // Filter to department's assigned tickets
        const filtered = all.filter(
          (g) => g.assigned_department_id === currentUser.department_id
        );
        setTickets(filtered);
      } catch (e) {
        console.warn('Failed to load department tickets', e);
      }
    };
    load();
  }, [currentUser]);

  return (
    <div className="p-4">
      <button onClick={onBack} className="mb-4 text-blue-500">
        ← Back to Home
      </button>
      <h2 className="text-xl font-bold mb-4">
        Department Dashboard – {currentUser.department_name || 'Dept'}
      </h2>
      {tickets.length === 0 ? (
        <p>No grievances assigned to your department.</p>
      ) : (
        <ul className="space-y-2">
          {tickets.map((t) => (
            <li key={t.id} className="border p-2 rounded">
              <strong>{t.title || t.category}</strong>
              <p>{t.description?.slice(0, 100)}…</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
"

